def remove_adjacent_dup_pairs(items):
    """反复删除列表中相邻的重复对。"""
    while True:
        new_items = []
        has_duplicates = False
        for i in range(len(items)):
            if i > 0 and items[i] == items[i - 1]:
                has_duplicates = True
                continue
            new_items.append(items[i])
        if not has_duplicates:
            break
        items = new_items
    return items
```

