    while True:
        new_items = []
        i = 0
        while i < len(items):
            if i + 1 < len(items) and items[i] == items[i + 1]:
                i += 2
            else:
                new_items.append(items[i])
                i += 1
        if len(new_items) == len(items):
            break
        items = new_items
    return items
