def remove_bracket_pairs(s):
    """反复删除相邻的配对括号。"""
    pairs = {"()": "", "[]": "", "{}": ""}
    while True:
        new_s = s
        for pair, replacement in pairs.items():
            new_s = new_s.replace(pair, replacement)
        if new_s == s:
            break
        s = new_s
    return s
